use std::collections::BTreeSet;
use std::io::{self, Read};

const ROWS: usize = 20;
const NCELLS: usize = 10 * ROWS;
const LIMIT: i128 = 1_000_000_000_000;

#[derive(Clone, Copy, PartialEq)]
enum Fault {
    Value,
    Div0,
    Overflow,
}

impl Fault {
    fn name(self) -> &'static str {
        match self {
            Fault::Value => "#VALUE",
            Fault::Div0 => "#DIV0",
            Fault::Overflow => "#OVERFLOW",
        }
    }
}

type Val = Result<i64, Fault>;

fn chk(v: i128) -> Val {
    if v.abs() > LIMIT {
        Err(Fault::Overflow)
    } else {
        Ok(v as i64)
    }
}

#[derive(Clone, Copy, PartialEq)]
enum Func {
    Sum,
    Min,
    Max,
    Count,
    Abs,
}

enum Expr {
    Num(i64),
    Ref(usize),
    Neg(Box<Expr>),
    Bin(char, Box<Expr>, Box<Expr>),
    Call(Func, Vec<Arg>),
}

enum Arg {
    /// Member cells of a range, row by row.
    Range(Vec<usize>),
    Scalar(Expr),
}

enum Cell {
    Empty,
    Num(i64),
    Text(String),
    Formula { expr: Expr, deps: Vec<usize> },
}

#[derive(Clone, PartialEq)]
enum Tok {
    Num(i64),
    Cell(usize),
    Func(Func),
    Op(char),
}

/// Cell index is column * ROWS + (row - 1); this order is also the dump order.
fn parse_cell(s: &str) -> Option<usize> {
    let b = s.as_bytes();
    if b.len() < 2 || b.len() > 3 || !(b'A'..=b'J').contains(&b[0]) {
        return None;
    }
    if b[1] == b'0' || !b[1..].iter().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let r: usize = s[1..].parse().ok()?;
    if (1..=ROWS).contains(&r) {
        Some(((b[0] - b'A') as usize) * ROWS + r - 1)
    } else {
        None
    }
}

fn cell_name(i: usize) -> String {
    format!("{}{}", (b'A' + (i / ROWS) as u8) as char, i % ROWS + 1)
}

fn is_number(s: &str) -> bool {
    let d = s.strip_prefix('-').unwrap_or(s);
    (1..=9).contains(&d.len()) && d.bytes().all(|c| c.is_ascii_digit())
}

fn tokenize(s: &str) -> Option<Vec<Tok>> {
    let b = s.as_bytes();
    let mut toks = Vec::new();
    let mut i = 0;
    while i < b.len() {
        let ch = b[i];
        if ch == b' ' {
            i += 1;
        } else if ch.is_ascii_digit() {
            let st = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            if i - st > 9 {
                return None;
            }
            toks.push(Tok::Num(s[st..i].parse().ok()?));
        } else if ch.is_ascii_alphabetic() {
            let st = i;
            while i < b.len() && b[i].is_ascii_alphanumeric() {
                i += 1;
            }
            let w = &s[st..i];
            toks.push(match w {
                "SUM" => Tok::Func(Func::Sum),
                "MIN" => Tok::Func(Func::Min),
                "MAX" => Tok::Func(Func::Max),
                "COUNT" => Tok::Func(Func::Count),
                "ABS" => Tok::Func(Func::Abs),
                _ => Tok::Cell(parse_cell(w)?),
            });
        } else if b"+-*/(),:".contains(&ch) {
            toks.push(Tok::Op(ch as char));
            i += 1;
        } else {
            return None;
        }
    }
    Some(toks)
}

struct Parser {
    toks: Vec<Tok>,
    pos: usize,
}

impl Parser {
    fn is_op(&self, c: char) -> bool {
        self.toks.get(self.pos) == Some(&Tok::Op(c))
    }

    fn expect_op(&mut self, c: char) -> Option<()> {
        if self.is_op(c) {
            self.pos += 1;
            Some(())
        } else {
            None
        }
    }

    fn expr(&mut self) -> Option<Expr> {
        let mut e = self.term()?;
        loop {
            let op = if self.is_op('+') {
                '+'
            } else if self.is_op('-') {
                '-'
            } else {
                break;
            };
            self.pos += 1;
            let r = self.term()?;
            e = Expr::Bin(op, Box::new(e), Box::new(r));
        }
        Some(e)
    }

    fn term(&mut self) -> Option<Expr> {
        let mut e = self.unary()?;
        loop {
            let op = if self.is_op('*') {
                '*'
            } else if self.is_op('/') {
                '/'
            } else {
                break;
            };
            self.pos += 1;
            let r = self.unary()?;
            e = Expr::Bin(op, Box::new(e), Box::new(r));
        }
        Some(e)
    }

    fn unary(&mut self) -> Option<Expr> {
        if self.is_op('-') {
            self.pos += 1;
            Some(Expr::Neg(Box::new(self.unary()?)))
        } else {
            self.primary()
        }
    }

    fn primary(&mut self) -> Option<Expr> {
        let t = self.toks.get(self.pos)?.clone();
        self.pos += 1;
        match t {
            Tok::Num(n) => Some(Expr::Num(n)),
            Tok::Cell(i) => Some(Expr::Ref(i)),
            Tok::Op('(') => {
                let e = self.expr()?;
                self.expect_op(')')?;
                Some(e)
            }
            Tok::Func(f) => {
                self.expect_op('(')?;
                let mut args = vec![self.arg()?];
                while self.is_op(',') {
                    self.pos += 1;
                    args.push(self.arg()?);
                }
                self.expect_op(')')?;
                if f == Func::Abs && (args.len() != 1 || matches!(args[0], Arg::Range(_))) {
                    return None;
                }
                Some(Expr::Call(f, args))
            }
            _ => None,
        }
    }

    fn arg(&mut self) -> Option<Arg> {
        if let (Some(Tok::Cell(a)), Some(Tok::Op(':'))) =
            (self.toks.get(self.pos), self.toks.get(self.pos + 1))
        {
            let a = *a;
            self.pos += 2;
            let b = match self.toks.get(self.pos) {
                Some(Tok::Cell(b)) => *b,
                _ => return None,
            };
            self.pos += 1;
            let (ca, ra) = (a / ROWS, a % ROWS);
            let (cb, rb) = (b / ROWS, b % ROWS);
            let mut members = Vec::new();
            for r in ra.min(rb)..=ra.max(rb) {
                for c in ca.min(cb)..=ca.max(cb) {
                    members.push(c * ROWS + r);
                }
            }
            return Some(Arg::Range(members));
        }
        Some(Arg::Scalar(self.expr()?))
    }
}

fn parse(src: &str) -> Option<Expr> {
    let mut p = Parser { toks: tokenize(src)?, pos: 0 };
    let e = p.expr()?;
    if p.pos != p.toks.len() {
        return None;
    }
    Some(e)
}

fn collect_expr(e: &Expr, out: &mut BTreeSet<usize>) {
    match e {
        Expr::Num(_) => {}
        Expr::Ref(i) => {
            out.insert(*i);
        }
        Expr::Neg(x) => collect_expr(x, out),
        Expr::Bin(_, a, b) => {
            collect_expr(a, out);
            collect_expr(b, out);
        }
        Expr::Call(_, args) => {
            for a in args {
                match a {
                    Arg::Range(m) => out.extend(m.iter().copied()),
                    Arg::Scalar(x) => collect_expr(x, out),
                }
            }
        }
    }
}

fn cell_val(cells: &[Cell], i: usize, cache: &mut [Option<Val>]) -> Val {
    if let Some(v) = cache[i] {
        return v;
    }
    let v = match &cells[i] {
        Cell::Empty => Ok(0),
        Cell::Num(n) => Ok(*n),
        Cell::Text(_) => Err(Fault::Value),
        Cell::Formula { expr, .. } => eval(expr, cells, cache),
    };
    cache[i] = Some(v);
    v
}

fn eval(e: &Expr, cells: &[Cell], cache: &mut [Option<Val>]) -> Val {
    match e {
        Expr::Num(n) => Ok(*n),
        Expr::Ref(i) => cell_val(cells, *i, cache),
        Expr::Neg(x) => Ok(-eval(x, cells, cache)?),
        Expr::Bin(op, a, b) => {
            let x = eval(a, cells, cache)? as i128;
            let y = eval(b, cells, cache)? as i128;
            match *op {
                '+' => chk(x + y),
                '-' => chk(x - y),
                '*' => chk(x * y),
                _ => {
                    if y == 0 {
                        Err(Fault::Div0)
                    } else {
                        chk(x / y)
                    }
                }
            }
        }
        Expr::Call(f, args) => call(*f, args, cells, cache),
    }
}

struct Acc {
    f: Func,
    sum: i64,
    count: i64,
    min: Option<i64>,
    max: Option<i64>,
}

impl Acc {
    fn add(&mut self, v: i64) -> Result<(), Fault> {
        self.count += 1;
        if self.f == Func::Sum {
            self.sum = chk(self.sum as i128 + v as i128)?;
        }
        self.min = Some(self.min.map_or(v, |m| m.min(v)));
        self.max = Some(self.max.map_or(v, |m| m.max(v)));
        Ok(())
    }

    fn finish(&self) -> Val {
        match self.f {
            Func::Sum => Ok(self.sum),
            Func::Count => Ok(self.count),
            Func::Min => self.min.ok_or(Fault::Value),
            Func::Max => self.max.ok_or(Fault::Value),
            Func::Abs => unreachable!("ABS is handled in call"),
        }
    }
}

fn call(f: Func, args: &[Arg], cells: &[Cell], cache: &mut [Option<Val>]) -> Val {
    if let (Func::Abs, [Arg::Scalar(e)]) = (f, args) {
        return Ok(eval(e, cells, cache)?.abs());
    }
    let mut acc = Acc { f, sum: 0, count: 0, min: None, max: None };
    for a in args {
        match a {
            Arg::Scalar(e) => {
                let v = eval(e, cells, cache)?;
                acc.add(v)?;
            }
            Arg::Range(members) => {
                for &i in members {
                    match &cells[i] {
                        Cell::Empty | Cell::Text(_) => {}
                        Cell::Num(n) => acc.add(*n)?,
                        Cell::Formula { .. } => {
                            let v = cell_val(cells, i, cache)?;
                            acc.add(v)?;
                        }
                    }
                }
            }
        }
    }
    acc.finish()
}

fn show(cells: &[Cell], i: usize, cache: &mut [Option<Val>]) -> String {
    match &cells[i] {
        Cell::Empty => "(empty)".to_string(),
        Cell::Num(n) => n.to_string(),
        Cell::Text(s) => s.clone(),
        Cell::Formula { .. } => match cell_val(cells, i, cache) {
            Ok(n) => n.to_string(),
            Err(f) => f.name().to_string(),
        },
    }
}

/// Depth-first search from `target` along dependencies; returns the first path back to `target`.
fn find_cycle(
    target: usize,
    deps: &[usize],
    cells: &[Cell],
    path: &mut Vec<usize>,
    visited: &mut [bool],
) -> Option<Vec<usize>> {
    for &d in deps {
        if d == target {
            let mut p = path.clone();
            p.push(target);
            return Some(p);
        }
        if visited[d] {
            continue;
        }
        visited[d] = true;
        path.push(d);
        let next: &[usize] = match &cells[d] {
            Cell::Formula { deps, .. } => deps.as_slice(),
            _ => &[],
        };
        if let Some(p) = find_cycle(target, next, cells, path, visited) {
            return Some(p);
        }
        path.pop();
    }
    None
}

fn bad_command(out: &mut String) {
    out.push_str("error: bad command\n");
}

fn set(cells: &mut [Cell], line: &str, out: &mut String) {
    let (name, content) = match line.strip_prefix("set ").and_then(|r| r.split_once(' ')) {
        Some((n, c)) if !c.is_empty() => (n, c),
        _ => return bad_command(out),
    };
    let i = match parse_cell(name) {
        Some(i) => i,
        None => return bad_command(out),
    };
    let new_cell = if let Some(src) = content.strip_prefix('=') {
        let expr = match parse(src) {
            Some(e) => e,
            None => {
                out.push_str("error: bad formula\n");
                return;
            }
        };
        let mut set = BTreeSet::new();
        collect_expr(&expr, &mut set);
        let deps: Vec<usize> = set.into_iter().collect();
        let mut path = vec![i];
        let mut visited = vec![false; NCELLS];
        if let Some(p) = find_cycle(i, &deps, cells, &mut path, &mut visited) {
            let names: Vec<String> = p.iter().map(|&c| cell_name(c)).collect();
            out.push_str(&format!("error: cycle {}\n", names.join(" -> ")));
            return;
        }
        Cell::Formula { expr, deps }
    } else if is_number(content) {
        Cell::Num(content.parse().unwrap())
    } else {
        Cell::Text(content.to_string())
    };
    cells[i] = new_cell;
}

fn dump(cells: &[Cell], out: &mut String) {
    let mut cache = vec![None; NCELLS];
    let mut any = false;
    for i in 0..NCELLS {
        if matches!(cells[i], Cell::Empty) {
            continue;
        }
        any = true;
        let v = show(cells, i, &mut cache);
        out.push_str(&format!("{} = {}\n", cell_name(i), v));
    }
    if !any {
        out.push_str("(empty sheet)\n");
    }
}

fn run(cells: &mut [Cell], line: &str, out: &mut String) {
    let f: Vec<&str> = line.split(' ').collect();
    let one_cell = if f.len() == 2 { parse_cell(f[1]) } else { None };
    match f[0] {
        "set" => set(cells, line, out),
        "clear" => match one_cell {
            Some(i) => cells[i] = Cell::Empty,
            None => bad_command(out),
        },
        "get" => match one_cell {
            Some(i) => {
                let mut cache = vec![None; NCELLS];
                let v = show(cells, i, &mut cache);
                out.push_str(&format!("{} = {}\n", cell_name(i), v));
            }
            None => bad_command(out),
        },
        "dump" if f.len() == 1 => dump(cells, out),
        _ => bad_command(out),
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut cells: Vec<Cell> = (0..NCELLS).map(|_| Cell::Empty).collect();
    let mut out = String::new();
    for line in input.lines() {
        if line.trim().is_empty() {
            continue;
        }
        run(&mut cells, line, &mut out);
    }
    print!("{}", out);
}
